SELECT * FROM user_coupon
WHERE user_id = #{userId} AND coupon_id = #{couponId}
LIMIT 1

SELECT uc.user_coupon_id as userCouponId, uc.coupon_id as couponId, uc.status, uc.get_time as getTime, uc.use_time as useTime, c.name, c.type, c.amount, c.min_point as minPoint, c.start_time as startTime, c.end_time as endTime FROM user_coupon uc LEFT JOIN coupon c ON uc.coupon_id = c.coupon_id WHERE uc.user_id = #{userId}
AND uc.status = #{status}
ORDER BY uc.created_at DESC

mapper.update:
UPDATE user_coupon
SET status = 1, use_time = #{useTime}
WHERE user_coupon_id = #{userCouponId}
AND status = 0
